using CleanArchitecture.Blazor.Application.Features.ITSystems.Caching;

namespace CleanArchitecture.Blazor.Application.Features.ITSystems.Commands.Delete;

public class DeleteITSystemCommand : ICacheInvalidatorRequest<Result<int>>
{
    public DeleteITSystemCommand(int[] ids)
    {
        Ids = ids;
    }

    [Description("Ids")]
    public int[] Ids { get; set; }

    public string CacheKey => ITSystemCacheKey.GetAllCacheKey;
    public IEnumerable<string>? Tags => ITSystemCacheKey.Tags;
}

public class DeleteITSystemCommandHandler : IRequestHandler<DeleteITSystemCommand, Result<int>>
{
    private readonly IApplicationDbContextFactory _dbContextFactory;

    public DeleteITSystemCommandHandler(
        IApplicationDbContextFactory dbContextFactory
    )
    {
        _dbContextFactory = dbContextFactory;
    }

    public async Task<Result<int>> Handle(DeleteITSystemCommand request, CancellationToken cancellationToken)
    {
        await using var db = await _dbContextFactory.CreateAsync(cancellationToken);
        var items = await db.ITSystems.Where(x => request.Ids.Contains(x.Id)).ToListAsync(cancellationToken);
        
        if (items.Count == 0)
        {
            return await Result<int>.FailureAsync("IT Systems not found.");
        }

        foreach (var item in items)
        {
            item.AddDomainEvent(new ITSystemDeletedEvent(item));
            db.ITSystems.Remove(item);
        }

        var result = await db.SaveChangesAsync(cancellationToken);
        return await Result<int>.SuccessAsync(result);
    }
}